#!/usr/bin/env python3
import json
import os
import re
import sys
import xml.etree.ElementTree as ET

NS = {"hp": "http://www.hancom.co.kr/hwpml/2010/HWPML"}
HP_NS = NS["hp"]

def qname(local: str) -> str:
    return f"{{{HP_NS}}}{local}"

def yyyy_mm_dd_to_dots(s: str) -> str:
    # Strictly convert YYYY-MM-DD -> YYYY.MM.DD when applicable
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", s or ""):
        return s.replace("-", ".")
    return s

def risk_note(tier: str) -> str:
    return {
        "High": " 즉시조치",
        "Medium": " 계획보완",
        "Low": " 모니터링",
    }.get(tier, "")

def annotate_risk_tier(tier: str) -> str:
    return f"{tier}{risk_note(tier)}" if tier else tier


def load_json(path: str):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def build_mapping(overview_path: str, actions_path: str):
    overview = load_json(overview_path)
    actions = load_json(actions_path)

    summary = overview.get("summary", {})

    inspection_date_raw = summary.get("점검일", "")
    inspection_date_fmt = yyyy_mm_dd_to_dots(inspection_date_raw)

    tier_raw = summary.get("위험등급", "")
    tier_annotated = annotate_risk_tier(tier_raw)

    immediate_actions = actions.get("immediate_actions", [])
    # Contract says there are 3 lines; be conservative and fill missing as blank.
    act1 = immediate_actions[0] if len(immediate_actions) > 0 else ""
    act2 = immediate_actions[1] if len(immediate_actions) > 1 else ""
    act3 = immediate_actions[2] if len(immediate_actions) > 2 else ""

    mapping = {
        "{{점검ID}}": str(summary.get("점검ID", "")),
        "{{현장명}}": str(summary.get("현장명", "")),
        "{{주관점검자}}": str(summary.get("주관점검자", "")),
        "{{점검일}}": inspection_date_fmt,
        "{{위험등급}}": tier_annotated,
        "{{총평}}": str(summary.get("총평", "")),
        "{{보고대상}}": str(summary.get("보고대상", "")),
        "{{조치1}}": str(act1),
        "{{조치2}}": str(act2),
        "{{조치3}}": str(act3),
    }

    return {
        "mapping": mapping,
        "inspection_date_raw": inspection_date_raw,
        "inspection_date_fmt": inspection_date_fmt,
        "tier_raw": tier_raw,
        "tier_annotated": tier_annotated,
    }


def replace_in_section_xml(xml_path: str, mapping: dict, date_raw: str, date_fmt: str, tier_raw: str, tier_annotated: str):
    # Preserve XML declaration by writing bytes with encoding.
    parser = ET.XMLParser(encoding="utf-8")
    tree = ET.parse(xml_path, parser=parser)
    root = tree.getroot()

    modified_paras = 0

    # Iterate paragraphs
    for p in root.findall(".//hp:p", NS):
        para_modified = False

        # Replace placeholders inside each text run
        for t in p.findall(".//hp:t", NS):
            if t.text is None:
                continue
            original = t.text
            new = original

            # Apply placeholder mapping
            for k, v in mapping.items():
                if k in new:
                    new = new.replace(k, v)

            # Convert the inspection date wherever it appears literally
            if date_raw and date_raw in new:
                new = new.replace(date_raw, date_fmt)

            # Ensure risk tier text includes severity note everywhere it appears.
            # Avoid double-annotating.
            if tier_raw:
                if tier_annotated in new:
                    pass
                else:
                    # Word-boundary replace for ASCII tiers (High/Medium/Low)
                    new = re.sub(rf"\b{re.escape(tier_raw)}\b", tier_annotated, new)

            if new != original:
                t.text = new
                para_modified = True

        if para_modified:
            # Remove line segment arrays (case variants) to avoid overlapping rendering.
            removed_any = False
            for child in list(p):
                if child.tag in (qname("linesegarray"), qname("lineSegArray")):
                    p.remove(child)
                    removed_any = True
            # Some templates nest linesegarray not as direct child; remove descendants too.
            for ls in list(p.findall(".//hp:linesegarray", NS)):
                parent = _find_parent(root, ls)
                if parent is not None:
                    parent.remove(ls)
                    removed_any = True
            for ls in list(p.findall(".//hp:lineSegArray", NS)):
                parent = _find_parent(root, ls)
                if parent is not None:
                    parent.remove(ls)
                    removed_any = True

            modified_paras += 1

    # Write back
    tree.write(xml_path, encoding="utf-8", xml_declaration=True)
    return modified_paras


def _find_parent(root: ET.Element, target: ET.Element):
    # ElementTree doesn't provide parent pointers.
    for parent in root.iter():
        for child in list(parent):
            if child is target:
                return parent
    return None


def main():
    if len(sys.argv) != 4:
        print("Usage: fill_hwpx.py <overview_json> <actions_json> <extracted_dir>", file=sys.stderr)
        return 2

    overview_json, actions_json, extracted_dir = sys.argv[1:4]

    built = build_mapping(overview_json, actions_json)
    mapping = built["mapping"]

    contents_dir = os.path.join(extracted_dir, "Contents")
    if not os.path.isdir(contents_dir):
        raise SystemExit(f"Contents directory not found: {contents_dir}")

    xml_files = [
        os.path.join(contents_dir, f)
        for f in os.listdir(contents_dir)
        if f.lower().endswith(".xml")
    ]

    total_modified = 0
    for xp in sorted(xml_files):
        total_modified += replace_in_section_xml(
            xp,
            mapping=mapping,
            date_raw=built["inspection_date_raw"],
            date_fmt=built["inspection_date_fmt"],
            tier_raw=built["tier_raw"],
            tier_annotated=built["tier_annotated"],
        )

    # Sanity check: no placeholders left
    leftovers = []
    placeholder_re = re.compile(r"\{\{[^}]+\}\}")
    for xp in sorted(xml_files):
        with open(xp, "r", encoding="utf-8") as f:
            text = f.read()
        m = placeholder_re.search(text)
        if m:
            leftovers.append((xp, m.group(0)))

    if leftovers:
        for xp, token in leftovers:
            print(f"ERROR: leftover placeholder {token} in {xp}")
        return 1

    print(f"OK: modified paragraphs: {total_modified}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

